using System.Diagnostics;
using System.Text;
using System.Text.Json;
namespace Cortex.Video.Composition;
/// <summary>Calls the engine's JSON protocol with explicit host paths and argument vectors, never a shell. An optional host-owned
/// Helengine project directory adds that project's <c>.heffect</c> effects to the engine catalog for every command.</summary>
public sealed class HelengineCompositionClient(string cliPath,string ffmpegExecutable="ffmpeg",string dotnetExecutable="dotnet",string? projectDirectory=null):IHelengineCompositionClient {
    public async Task<HelengineCapabilities> CapabilitiesAsync(CancellationToken token) {var result=await RunAsync(projectDirectory is null?["composition","capabilities","--json"]:["composition","capabilities","--project",Path.GetFullPath(projectDirectory),"--json"],token);using var document=JsonDocument.Parse(result);return HelengineCapabilities.Parse(document.RootElement);}
    public async Task ValidateAsync(JsonElement composition,string assetsRoot,CancellationToken token) {string input=await WriteInput(composition,assetsRoot,token);try {await RunAsync(["composition","validate","--input",input,"--assets-root",Path.GetFullPath(assetsRoot)],token);}finally {File.Delete(input);}}
    public async Task<JsonElement> RenderAsync(JsonElement composition,string assetsRoot,string output,string profile,CancellationToken token) {string input=await WriteInput(composition,assetsRoot,token);try {string json=await RunAsync(["composition","render","--input",input,"--assets-root",Path.GetFullPath(assetsRoot),"--out",Path.GetFullPath(output),"--profile",profile,"--ffmpeg",ffmpegExecutable],token);using var document=JsonDocument.Parse(json);return document.RootElement.Clone();}finally {File.Delete(input);}}
    public async Task FrameAsync(JsonElement composition,string assetsRoot,string output,long numerator,long denominator,int width,int height,CancellationToken token) {string input=await WriteInput(composition,assetsRoot,token);try {await RunAsync(["composition","frame","--input",input,"--assets-root",Path.GetFullPath(assetsRoot),"--out",Path.GetFullPath(output),"--time",numerator+"/"+denominator,"--width",width.ToString(System.Globalization.CultureInfo.InvariantCulture),"--height",height.ToString(System.Globalization.CultureInfo.InvariantCulture)],token);}finally {File.Delete(input);}}
    private static async Task<string> WriteInput(JsonElement composition,string root,CancellationToken token) {if(composition.ValueKind!=JsonValueKind.Object || composition.GetProperty("schema").GetString()!="helengine.media.composition.v1")throw new InvalidDataException("Not an executable engine composition.");string text=composition.GetRawText();if(text.Length>4194304)throw new InvalidDataException("Composition exceeds protocol limit.");string directory=Path.GetFullPath(root);if(!Directory.Exists(directory))throw new DirectoryNotFoundException(directory);string input=Path.Combine(directory,".composition-"+Guid.NewGuid().ToString("N")+".json");await File.WriteAllTextAsync(input,text,token);return input;}
    private async Task<string> RunAsync(IReadOnlyList<string> arguments,CancellationToken token) {
        if(string.IsNullOrWhiteSpace(cliPath) || !File.Exists(cliPath))throw new FileNotFoundException("Helengine composition CLI is not installed.",cliPath);bool dll=cliPath.EndsWith(".dll",StringComparison.OrdinalIgnoreCase);var start=new ProcessStartInfo(dll?dotnetExecutable:cliPath){UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true};if(dll)start.ArgumentList.Add(Path.GetFullPath(cliPath));foreach(string argument in arguments)start.ArgumentList.Add(argument);if(projectDirectory is not null && arguments[1]!="capabilities") {start.ArgumentList.Add("--project");start.ArgumentList.Add(Path.GetFullPath(projectDirectory));}using var process=Process.Start(start)??throw new IOException("Could not start Helengine composition CLI.");using var registration=token.Register(()=>{try {if(!process.HasExited)process.Kill(true);}catch(InvalidOperationException){}});Task<string> output=ReadBounded(process.StandardOutput,262144);Task<string> error=ReadBounded(process.StandardError,16384);try {await process.WaitForExitAsync(token);}catch {if(!process.HasExited)process.Kill(true);await process.WaitForExitAsync(CancellationToken.None);await Task.WhenAll(output,error);throw;}await Task.WhenAll(output,error);if(process.ExitCode!=0)throw new InvalidDataException("Helengine composition failed: "+await error+" "+await output);return await output;
    }
    private static async Task<string> ReadBounded(StreamReader reader,int limit) {var text=new StringBuilder();char[] buffer=new char[2048];int count;while((count=await reader.ReadAsync(buffer))>0) {text.Append(buffer,0,count);if(text.Length>limit)text.Remove(0,text.Length-limit);}return text.ToString();}
}
